from collections import deque

def gp(n,k):
 edges=[]
 for i in range(n):
  edges.append((i,(i+1)%n))
  edges.append((i,n+i))
  a=n+i; b=n+((i+k)%n)
  if a<b: edges.append((a,b))
  else: edges.append((b,a))
 return list(set(tuple(sorted(e)) for e in edges))

def girth(N,edges):
 adj=[set() for _ in range(N)]
 for a,b in edges: adj[a].add(b); adj[b].add(a)
 g=999
 for s in range(N):
  dist=[-1]*N; par=[-1]*N; dist[s]=0; q=deque([s])
  while q:
   v=q.popleft()
   for u in adj[v]:
    if dist[u]<0:
     dist[u]=dist[v]+1; par[u]=v; q.append(u)
    elif par[v]!=u and par[u]!=v:
     g=min(g,dist[v]+dist[u]+1)
 return g if g<999 else None
for n in range(7,30):
 for k in range(2,n//2+1):
